Here is an example of a JavaScript function that converts an array with three elements to a JSON object, with validation:
```
function arrayToJsonObject(arr) {
  if (!Array.isArray(arr) || arr.length !== 3) {
    throw new Error("Invalid input: array must have exactly 3 elements");
  }

  const [str, num, float] = arr;

  if (typeof str !== "string") {
    throw new Error("Invalid input: first element must be a string");
  }

  if (!Number.isInteger(num)) {
    throw new Error("Invalid input: second element must be an integer");
  }

  if (typeof float !== "number" || !isFinite(float) || float % 1 === 0) {
    throw new Error("Invalid input: third element must be a float");
  }

  return {
    str: str,
    num: num,
    float: float
  };
}
```
