Build a Cloud Function using Node.js that takes New York Times' Article Search API to find articles based on specific keywords. The function should be triggered by an HTTP request and should include parameters for sorting and filtering results based on publish date, section, and author. It should return a JSON object with a list of articles that match the search criteria including title, URL, abstract, and publish date. The response should be paginated with a maximum of 20 results per page.

Here is an example of a Cloud Function using Node.js that meets the requirements:
```
const axios = require('axios');

exports.searchArticles = async (req, res) => {
  const apiKey = 'YOUR_NYT_API_KEY';
  const apiEndpoint = 'https://api.nytimes.com/svc/search/v2/articlesearch.json';

  const { keywords, sort, filterSection, filterAuthor, page } = req.query;

  const params = {
    'api-key': apiKey,
    q: keywords,
    sort: sort || 'newest',
    fl: 'title,url,abstract,pub_date',
    fq: []
  };

  if (filterSection) {
    params.fq.push(`section_name:(${filterSection})`);
  }

  if (filterAuthor) {
    params.fq.push(`byline.person:(${filterAuthor})`);
  }

  params.page = page || 0;

  try {
    const response = await axios.get(apiEndpoint, { params });
    const data = response.data.response.docs;

    const articles = data.map((article) => ({
      title: article.headline.main,
      url: article.web_url,
      abstract: article.abstract,
      publishDate: article.pub_date
    }));

    const pagination = {
      currentPage: params.page,
      totalPages: Math.ceil(response.data.response.meta.hits / 20),
      hasNextPage: params.page < Math.ceil(response.data.response.meta.hits / 20) - 1
    };

    res.json({ articles, pagination });
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Error searching for articles' });
  }
};
```
Here's an explanation of the code:

* The function takes in an HTTP request with query parameters for `keywords`, `sort`, `filterSection`, `filterAuthor`, and `page`.
* The function uses the `axios` library to make a GET request to the New York Times' Article Search API.
* The `params` object is constructed with the required API key, search query, and optional sorting and filtering parameters.
* The `fl` parameter specifies the fields to return in the response, and the `fq` parameter specifies the filters to apply to the search results.
* The `page` parameter is used to paginate the results, with a maximum of 20 results per page

