function callPythonScript(arg1: string, arg2: number) {
  return new Promise((resolve, reject) => {
    const pythonProcess = childProcess.spawn('python', [pythonScriptPath, arg1, arg2.toString()]);

    let output = '';
    pythonProcess.stdout.on('data', (data) => {
      output += data.toString();
    });

    pythonProcess.on('close', (code) => {
      if (code !== 0) {
        reject(new Error(`Python script failed with code ${code}`));
      } else {
        try {
          const parsedOutput: PythonScriptOutput = JSON.parse(output);
          resolve(parsedOutput);
        } catch (error) {
          reject(error);
        }
      }
    });
  });
}

